A expressão de consulta mostrada a seguir apresenta como
resultado o local da sede, a área da sala e a descrição da(s)
sala(s) com a maior área.
select c1.local, c1.nome, c2.descricao
from sede as c1,
(
select local, descricao, area from salas as c1
where area = (select max(area) from salas as
c2 where area>0)
) as c2 where c2.local=c1.apelido;

